/**
 * Synthetic harness for minutes-v1 vs the frozen baseline v0. No network, no
 * NBA.com data: everything is generated by __fixtures__/syntheticLeague.ts.
 *
 *   npm run nba:minutes-synthetic
 *   npm run nba:minutes-synthetic -- --seeds=1,2,3 --out=<file.json>
 *
 * Seasons: 2040-41 warm-up (history only), 2041-42 development (v0 priors and
 * v1 calibration), 2042-43 validation (scored), 2043-44 holdout (generated
 * but never scored here, mirroring the real protocol).
 *
 * The numbers are mechanism checks on a league whose effects were written by
 * the model's author. They are not evidence of real-world accuracy.
 */
import { writeFileSync } from "node:fs";
import { estimatePriors } from "../src/lib/nba/props/backtest";
import { DEFAULT_SYNTHETIC_LEAGUE, generateSyntheticLeague } from "../src/lib/nba/props/__fixtures__/syntheticLeague";
import {
  buildMinutesTargets,
  buildParticipationTargets,
  calibrateMinutesV1,
  evaluateMinutesV1,
  evaluateParticipation,
  scoreTargets,
  type EvaluationPeriod,
} from "../src/lib/nba/props/minutesV1Backtest";
import { DEFAULT_MINUTES_V1_PARAMS } from "../src/lib/nba/props/minutesV1";
import { BASELINE_V0_PUBLIC_PARAMS } from "../src/lib/nba/props/projection";
import { PROJECTED_STATS } from "../src/lib/nba/props/types";

const DEV: EvaluationPeriod = { name: "development", seasons: ["2041-42"], seasonTypes: ["regular"] };
const VALIDATION: EvaluationPeriod = { name: "validation", seasons: ["2042-43"], seasonTypes: ["regular"] };
const HOLDOUT_SEASONS = ["2043-44"];

function arg(name: string, fallback: string): string {
  const hit = process.argv.slice(2).find((value) => value.startsWith(`--${name}=`));
  return hit ? hit.slice(name.length + 3) : fallback;
}

const f = (value: number | null | undefined, digits = 3) => (value === null || value === undefined ? "—" : value.toFixed(digits));
const ci = (pair: [number, number] | null) => (pair ? `[${f(pair[0])}, ${f(pair[1])}]` : "—");

function runSeed(seed: number) {
  const league = generateSyntheticLeague({ ...DEFAULT_SYNTHETIC_LEAGUE, seed });
  const priors = estimatePriors(league.playerGames, DEV);
  const devParticipation = evaluateParticipation(buildParticipationTargets(league.playerGames, league.teamGames, DEV), DEFAULT_MINUTES_V1_PARAMS);
  const devTargets = buildMinutesTargets(league.playerGames, league.teamGames, DEV);
  const params = calibrateMinutesV1(devTargets, DEFAULT_MINUTES_V1_PARAMS, { holdoutSeasons: HOLDOUT_SEASONS, participationRate: devParticipation.observedRate });
  const validationTargets = buildMinutesTargets(league.playerGames, league.teamGames, VALIDATION);
  const evaluation = evaluateMinutesV1(scoreTargets(validationTargets, BASELINE_V0_PUBLIC_PARAMS, priors, params));
  const participation = evaluateParticipation(buildParticipationTargets(league.playerGames, league.teamGames, VALIDATION), params);
  return { seed, params, evaluation, participation, devTargets: devTargets.length, validationTargets: validationTargets.length };
}

function printSeed(result: ReturnType<typeof runSeed>): void {
  const { seed, evaluation, participation, params } = result;
  console.log(`\n=== seed ${seed}: dev ${result.devTargets} targets, validation ${result.validationTargets} targets ===`);
  console.log("calibrated ramp factors:", params.rampFactors.map((r) => f(r)).join(", "), "| sdPrior:", JSON.stringify(params.sdPrior), "| multipliers:", JSON.stringify(params.sdMultipliers));
  console.table(Object.fromEntries(PROJECTED_STATS.map((stat) => {
    const c = evaluation.overall[stat];
    return [stat, { "v0 MAE": f(c.maeV0), "v1 MAE": f(c.maeV1), "diff": f(c.byPlayer.meanDiff), "95% CI (player)": ci(c.byPlayer.ci95), "95% CI (14-day block)": ci(c.byTimeBlock.ci95) }];
  })));
  console.table(Object.fromEntries(Object.entries(evaluation.segments).map(([name, s]) => [name, {
    n: s.n, "v0 MAE": f(s.minutes.maeV0), "v1 MAE": f(s.minutes.maeV1), "95% CI (player)": ci(s.minutes.byPlayer.ci95), "95% CI (block)": ci(s.minutes.byTimeBlock.ci95),
  }])));
  console.log(`80% interval coverage ${f(evaluation.interval.coverage)} (mean width ${f(evaluation.interval.meanWidth, 1)} min);`,
    Object.entries(evaluation.interval.bySegment).map(([k, v]) => `${k} ${f(v.coverage, 2)} (n=${v.n})`).join(", "));
  console.log(`participation: n=${participation.n}, observed ${f(participation.observedRate)}, Brier v1 ${f(participation.brier.v1, 4)} vs constant ${f(participation.brier.constant, 4)}`);
}

function main(): void {
  const seeds = arg("seeds", String(DEFAULT_SYNTHETIC_LEAGUE.seed)).split(",").map(Number);
  if (seeds.some((seed) => !Number.isInteger(seed))) throw new Error("--seeds must be integers");
  const results = seeds.map(runSeed);
  results.forEach(printSeed);
  const out = arg("out", "");
  if (out) writeFileSync(out, `${JSON.stringify(results, null, 2)}\n`);
}

main();
